/* hook: the line streaks past; "nothing can reach you" lands on the word; then the checks stop */
tl.fromTo("#streaks1", { x: 0 }, { x: -900, duration: 8.6, ease: "none" }, 3.9);
tl.to("#chk3", { opacity: 1, duration: 0.2 }, 5.5);
tl.fromTo("#safe", { opacity: 0, y: -10 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 6.2);
tl.to("#checks", { opacity: 0.3, duration: 0.6 }, 10.1);
/* wide: the train crosses; the red zone flares on "20" */
tl.fromTo("#strip", { x: 0 }, { x: -640, duration: 6.6, ease: "none" }, 12.3);
tl.to("#zone", { opacity: 1, strokeWidth: 36, duration: 0.25, yoyo: true, repeat: 1 }, 16.9);
/* rule 1 obeyed: the lamp breathes but never goes out */
tl.fromTo("#held", { opacity: 0.45 }, { opacity: 1, duration: 0.5, yoyo: true, repeat: 3, ease: "sine.inOut" }, 26.4);
/* the plant: eleven light up as they are counted; the rest stay dark */
tl.fromTo("#c1,#c2,#c3,#c4,#c5,#c6,#c7,#c8,#c9,#c10,#c11", { opacity: 0.25 }, { opacity: 1, duration: 0.15, stagger: 0.07, ease: "none" }, 32.1);
tl.fromTo("#sealed", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 33.8);
/* rule 2 obeyed: the ring counts a block down; three blocks tick */
tl.fromTo("#ring", { drawSVG: "0% 100%" }, { drawSVG: "0% 0%", duration: 3.2, ease: "none" }, 41.3);
[41.92, 42.42, 42.95].forEach((t, i) => tl.to(`#t${i + 1}`, { opacity: 1, duration: 0.15 }, t));
/* the radio: the loop plays whole, every bar; the rig named through the scramble */
tl.to(".lb", { opacity: 0.9, duration: 0.1, stagger: 0.028, ease: "none" }, 45.7);
tl.set("#rigword", { textContent: "" }, 44.7);
tl.to("#rigword", { duration: 1.4, scrambleText: { text: "RIG BRAVO · 62 SOUTH", chars: "upperCase", speed: 0.6 } }, 49.5);
/* rule 3 obeyed: you pass what is on the line and do not stop */
tl.to("#traindot", { attr: { cy: 1380 }, duration: 5.3, ease: "none" }, 57.3);
/* 3:02: the streaks decelerate; the engine note drops; the lamp is still green */
tl.fromTo("#streaks2", { x: 0 }, { x: -700, duration: 9.6, ease: "power2.out" }, 62.8);
tl.to(".eb", { scaleY: 0.42, duration: 1.1, ease: "power2.inOut", stagger: 0.02 }, 65.4);
tl.fromTo("#held2", { opacity: 0.45 }, { opacity: 1, duration: 0.5, yoyo: true, repeat: 5, ease: "sine.inOut" }, 67.9);
/* the gauge: needle and readout fall on the spoken numbers */
tl.fromTo("#needle2", { rotation: 121.5, svgOrigin: "540 1000" }, { rotation: 108, duration: 1.2, ease: "none" }, 72.5);
[[74.26, 40, 90], [74.80, 31, 69.75], [75.47, 22, 49.5]].forEach(([t, v, a]) => {
  tl.to("#needle2", { rotation: a, svgOrigin: "540 1000", duration: 0.45, ease: "power2.out" }, t);
  tl.set("#spd", { textContent: String(v) }, t);
});
tl.to("#zone2", { opacity: 1, strokeWidth: 38, duration: 0.3, yoyo: true, repeat: 3 }, 75.5);
/* the recall: the brake, carriage 32, the one you did not check */
tl.fromTo("#brakestamp", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.32, ease: "power3.out" }, 79.2);
tl.fromTo("#c32hot", { opacity: 0 }, { opacity: 1, duration: 0.22, yoyo: true, repeat: 7 }, 80.7);
tl.fromTo("#unchecked", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.32, ease: "power3.out" }, 83.9);
